	private final Long2LongOpenHashMap literalSurvivorByLoser = new Long2LongOpenHashMap();
	private final Long2LongOpenHashMap tripleTermSurvivorByLoser = new Long2LongOpenHashMap();
	private final LongArrayList loserLiterals = new LongArrayList();
